+test("slugify converts input into a slug", () => {
+  expect(slugify("Hello, World!")).toBe("hello-world");
+});
diff --git a/src/index.ts b/src/index.ts
index 264d785..28d506c 100644
--- a/src/index.ts
+++ b/src/index.ts
@@ -2,3 +2,12 @@
 export function greet(name: string): string {
   return `Hello, ${name}!`;
 }
+
+/** Converts the given input into a URL-friendly slug. */
+export function slugify(input: string): string {
+  return input
+    .toLowerCase()
+    .trim()
+    .replace(/[^a-z0-9]+/g, "-")
+    .replace(/^-+|-+$/g, "");
+}
